import products from './products.json' with {type:'json'};

export async function listTools() {
  return [{
    name: 'inventory_search',
    description: 'Search inventory products by name',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Search query for product name' },
        limit: { type: 'integer', description: 'Max results (1-10)', minimum: 1, maximum: 10 }
      },
      required: ['query']
    }
  }];
}

export async function callTool(name, args = {}) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { query, limit } = args;

  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  let effectiveLimit;
  if (limit === undefined) {
    effectiveLimit = 10; // default? or no limit
  } else {
    if (!Number.isInteger(limit)) {
      throw new Error('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
    effectiveLimit = limit;
  }

  const q = query.toLowerCase();
  const matches = products.filter(p => p.name.toLowerCase().includes(q));
  const results = matches.slice(0, effectiveLimit);

  const text = results.length === 0
    ? 'No products found'
    : results.map(p => p.name).join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}
